function financePage(){if(!isFinance())financeTab='mine';const claims=data.claims||[];return heading('Reimbursements','Your expenses, handled by the General Secretaries.',button('New claim','claim-new','','plus'))+`<div class="tabs"><button data-cmd="finance-tab" data-value="mine" class="${financeTab==='mine'?'active':''}">My claims</button>${isFinance()?`<button data-cmd="finance-tab" data-value="desk" class="${financeTab==='desk'?'active':''}">${ic('lock')} Finance desk</button>`:''}</div><section class="panel"><div class="section-head"><h2>${financeTab==='desk'?'Claims to review':'Your reimbursement requests'}</h2>${link('Original form',resource('finance-form'),'quiet small-btn')}</div><p class="small">Bank details and receipts are restricted to the claimant and authorised finance users. A payment-status update here does not transfer money.</p>${(financeTab==='desk'?claims:claims.filter(c=>c.requester_id===me.id)).length?`<div class="table-wrap"><table><thead><tr><th>Event / purchase</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${(financeTab==='desk'?claims:claims.filter(c=>c.requester_id===me.id)).map(c=>`<tr><td><strong>${esc(c.event)}</strong><span class="small">${esc(c.items)}${financeTab==='desk'?'<br>'+esc(who(c.requester_id).name):''}</span></td><td>£${(c.amount_pence/100).toFixed(2)}</td><td><span class="tag ${c.status==='Paid'?'green':'amber'}">${esc(c.status)}</span></td><td>${button('View','claim','quiet small-btn','',`data-id="${esc(c.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No claims on this list.','Upload a receipt with your next expense request.','finance')}</section>`;}
