function filesPage(){return heading('Shared files','A place for the things the committee needs.',button('New folder','folder-new','secondary','plus'))+`<div class="file-toolbar"><div class="breadcrumbs"><button data-cmd="folder" data-id="">All files</button>${trail.map((f,i)=>`<span class="muted">/</span><button data-cmd="folder" data-id="${esc(f.id)}" data-depth="${i}">${esc(f.name)}</button>`).join('')}</div>${link('Existing OneDrive',resource('files-root'),'quiet small-btn')}</div><div class="dropzone" id="dropzone">${ic('upload')}<div><strong>Drop files here</strong><small>Images, documents and video · up to 20 MB each</small></div>${button('Browse','browse-files','secondary small-btn')}<input class="sr" id="file-picker" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.docx,.xlsx,.pptx,.txt,.csv,.mp4,.mp3"></div><p id="upload-progress" class="progress" role="status"></p><div class="filters"><div class="search">${ic('search')}<label class="sr" for="file-search">Search this folder</label><input id="file-search" placeholder="Find a file in this folder…" value="${esc(fileQuery)}"></div></div><div id="file-results"></div>`;}
function renderFiles(){const filtered=files.filter(f=>f.name.toLowerCase().includes(fileQuery.toLowerCase()));$('file-results').innerHTML=filtered.length?`<div class="file-grid">${filtered.map(f=>`<article class="file-card"><button data-cmd="${f.kind==='folder'?'folder':'file-open'}" data-id="${esc(f.id)}" data-name="${esc(f.name)}"><span class="thumb">${f.thumbnail?`<img alt="" src="${esc(f.thumbnail)}" loading="lazy">`:ic(f.kind==='folder'?'folder':'file')}</span><strong>${esc(f.name)}</strong><small>${f.kind==='folder'?'Folder':formatSize(f.size)} · ${date(f.created_at)}</small></button>${f.kind!=='folder'?`<div class="file-buttons">${button('Download','file-download','quiet small-btn','download',`data-id="${esc(f.id)}"`)}${f.owner_id===me.id||isExec()?`<button class="text-button danger-text" data-cmd="file-delete" data-id="${esc(f.id)}">Delete</button>`:''}</div>`:''}</article>`).join('')}</div>`:empty('A little space to get organised.','Create a folder or upload the first file.','folder');}
function formatSize(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.ceil(n/1024)+' KB';}
async function upload(file,scope='shared'){if(file.size>20*1024*1024)throw new Error(file.name+' exceeds 20 MB.');const p=await api('filePrepare',{name:file.name,size:file.size,mime:file.type,scope,parent:scope==='shared'?folder:null});const r=await fetch(p.upload_url,{method:'PUT',headers:{'Content-Type':p.mime,'x-upsert':'false'},body:file,signal:AbortSignal.timeout(120000)});if(!r.ok)throw new Error('Upload failed for '+file.name+'. Please try again.');await api('fileFinish',{id:p.id});return p.id;}
async function uploadFiles(list){if(busy)return;const incoming=[...list];if(!incoming.length)return;if(incoming.length>10){toast('Choose up to 10 files at a time.');return;}busy=true;try{for(let i=0;i<incoming.length;i++){if($('upload-progress'))$('upload-progress').textContent=`Uploading ${i+1} of ${incoming.length}: ${incoming[i].name}`;await upload(incoming[i]);}await loadFiles();renderFiles();toast('Files uploaded to the committee library.');}catch(e){toast(e.message);}finally{busy=false;if($('upload-progress'))$('upload-progress').textContent='';}}
async function openFile(id,download=false){const f=await api('fileRead',{id});const u=safeUrl(f.url);if(!u)throw new Error('File link unavailable.');if(!download&&/^image\/(png|jpeg|webp)$/.test(f.mime)){drawer(f.name,`<img class="preview-image" src="${esc(u)}" alt="${esc(f.name)}"><div class="form-actions">${button('Download','file-download','secondary','download',`data-id="${esc(id)}"`)}</div>`,'FILE PREVIEW');}else{const a=document.createElement('a');a.href=u;a.target='_blank';a.rel='noopener noreferrer';a.download=f.name;document.body.append(a);a.click();a.remove();}}
