function settingsPage(){if(!isAdmin())return '';return heading('Workspace settings','Access is controlled on the server, not by hiding pages.')+`<div class="settings-stack"><section class="panel"><div class="section-head"><h2>Approved committee accounts</h2>${button('Approve an email','member-new','','plus')}</div><p class="small">Members sign in with Google. No shared passwords. Only approved active accounts can access committee data.</p>${button('Manage approved accounts','members','secondary','people')}</section><section class="panel"><h2>Connected services</h2>${[['Google sign-in',true],['Private records',true],['Email delivery',data.services?.email],['Private shared files',data.services?.files],['Encrypted reimbursements',data.services?.finance],['Existing media-form import',data.services?.mediaImport]].map(([n,v])=>`<div class="integration"><span>${n}</span><span class="tag ${v?'green':'amber'}">${v?'Configured':'Not connected'}</span></div>`).join('')}<p class="small section-gap">Configured means credentials are present; complete end-to-end delivery tests before inviting the committee. ClickUp and OneDrive have not been modified or synchronised.</p></section><section class="panel"><h2>Existing forms and folders</h2><form id="resource-form"><div class="form-grid"><div class="field"><label for="f-key">Resource</label><select id="f-key" name="key">${options(['media-form','media-sheet','media-calendar','finance-form','finance-tracker','files-root'],'media-form')}</select></div>${field('Link','url','','url',false,'required placeholder="https://…"')}</div><div class="form-actions"><button type="submit" class="button">Save resource link</button></div></form></section></div>`;}
async function membersDialog(){const r=await api('memberList');drawer('Approved accounts',`${r.members.map(m=>`<div class="link-row"><div class="member-identity"><strong>${esc(m.name)}</strong><div class="small wrap-text">${esc(m.email)} · ${esc(m.role)}</div><span class="tag ${m.active?'green':'red'}">${m.active?'Active':'Revoked'}</span></div>${m.id!==me.id?button(m.active?'Revoke':'Restore','member-toggle','quiet small-btn','',`data-id="${esc(m.id)}" data-active="${!m.active}"`):'<span class="small">You</span>'}</div>`).join('')}<p class="small section-gap">Revoking access blocks the next API request, even if a Google session still exists.</p>`,'ADMINISTRATOR');}
